-- Run after seven initial DAG runs finish: all rows should be baseline
-- (INGESTED_AT is NULL) and all should have source SHA256.
SELECT 'CATEGORY' AS DATASET, COUNT(*) AS ROWS_LOADED, SUM(IFF(SOURCE_SHA256 IS NULL, 1, 0)) AS MISSING_SHA, SUM(IFF(INGESTED_AT IS NOT NULL, 1, 0)) AS INCREMENTAL_ROWS FROM ICOMMERCE.BRONZE.CATEGORY
UNION ALL SELECT 'SUB_CATEGORY', COUNT(*), SUM(IFF(SOURCE_SHA256 IS NULL, 1, 0)), SUM(IFF(INGESTED_AT IS NOT NULL, 1, 0)) FROM ICOMMERCE.BRONZE.SUB_CATEGORY
UNION ALL SELECT 'TYPE_CUSTOMER', COUNT(*), SUM(IFF(SOURCE_SHA256 IS NULL, 1, 0)), SUM(IFF(INGESTED_AT IS NOT NULL, 1, 0)) FROM ICOMMERCE.BRONZE.TYPE_CUSTOMER
UNION ALL SELECT 'CUSTOMER', COUNT(*), SUM(IFF(SOURCE_SHA256 IS NULL, 1, 0)), SUM(IFF(INGESTED_AT IS NOT NULL, 1, 0)) FROM ICOMMERCE.BRONZE.CUSTOMER
UNION ALL SELECT 'PRODUCT', COUNT(*), SUM(IFF(SOURCE_SHA256 IS NULL, 1, 0)), SUM(IFF(INGESTED_AT IS NOT NULL, 1, 0)) FROM ICOMMERCE.BRONZE.PRODUCT
UNION ALL SELECT 'SALE', COUNT(*), SUM(IFF(SOURCE_SHA256 IS NULL, 1, 0)), SUM(IFF(INGESTED_AT IS NOT NULL, 1, 0)) FROM ICOMMERCE.BRONZE.SALE
UNION ALL SELECT 'DETAIL_SALE', COUNT(*), SUM(IFF(SOURCE_SHA256 IS NULL, 1, 0)), SUM(IFF(INGESTED_AT IS NOT NULL, 1, 0)) FROM ICOMMERCE.BRONZE.DETAIL_SALE;
-- Expected row counts in order: 5, 18, 4, 17545, 3799, 505, 505.
-- MISSING_SHA and INCREMENTAL_ROWS = 0 for all seven datasets.
-- CUSTOMER has 17467 distinct keys; PRODUCT 3788. Duplicates remain for dbt.
